-- Preserve the two established permission states of legacy ordinary tables:
-- original owner-only, or the exact existing runtime provisioner profile. No
-- grants occur here. Extra roles, privileges and grant options remain visible.
CREATE FUNCTION public.shardkeep_vehicle_client_ordinary_acl(relation_name text,relation_owner oid,actual aclitem[]) RETURNS jsonb
LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $$
 WITH actual_rows AS (SELECT jsonb_build_array(grantor,grantee,privilege_type,is_grantable) v FROM aclexplode(coalesce(actual,acldefault('r',relation_owner)))),
 owner_rows AS (SELECT jsonb_build_array(grantor,grantee,privilege_type,is_grantable) v FROM aclexplode(acldefault('r',relation_owner))),
 runtime_rows AS (SELECT v FROM owner_rows UNION ALL SELECT jsonb_build_array(relation_owner,r.oid,p,false)
  FROM pg_roles r CROSS JOIN unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE']) p WHERE r.rolname IN('shardkeep_api_runtime','shardkeep_worker_runtime')),
 profiles AS (SELECT (SELECT jsonb_agg(v ORDER BY v::text) FROM actual_rows) actual_profile,
  (SELECT jsonb_agg(v ORDER BY v::text) FROM owner_rows) owner_profile,(SELECT jsonb_agg(v ORDER BY v::text) FROM runtime_rows) runtime_profile)
 SELECT CASE WHEN relation_name IN('crafting_stocks','ordinary_crafting_jobs','ordinary_crafting_inputs','ordinary_crafting_completions')
  AND (actual_profile=owner_profile OR ((SELECT count(*) FROM pg_roles WHERE rolname IN('shardkeep_api_runtime','shardkeep_worker_runtime'))=2 AND actual_profile=runtime_profile))
  THEN to_jsonb('original-or-existing-runtime-v1'::text) ELSE actual_profile END FROM profiles
$$;
REVOKE ALL ON FUNCTION public.shardkeep_vehicle_client_ordinary_acl(text,oid,aclitem[]) FROM PUBLIC;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION public.shardkeep_divine_fragment_contract() RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $$
