CREATE OR REPLACE FUNCTION public.shardkeep_vehicle_client_seal_guard() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$BEGIN
 IF TG_RELID<>'public.divine_fragment_vehicle_client_contract'::regclass OR TG_OP<>'INSERT' OR TG_WHEN<>'BEFORE' OR TG_LEVEL<>'ROW' OR TG_NAME<>'divine_fragment_vehicle_client_contract_guard'
 OR current_user<>session_user OR current_user::regrole::oid<>(SELECT relowner FROM pg_class WHERE oid=TG_RELID)
 OR current_setting('transaction_isolation')<>'read committed' OR current_setting('session_replication_role')<>'origin'
 OR EXISTS(SELECT 1 FROM public.divine_fragment_vehicle_client_contract)
 OR NEW.record IS DISTINCT FROM public.shardkeep_divine_fragment_contract() THEN RAISE EXCEPTION 'VEHICLE_CLIENT_SEAL_IMMUTABLE';END IF;RETURN NEW;
END $$;
CREATE TRIGGER divine_fragment_vehicle_client_contract_guard BEFORE INSERT OR UPDATE OR DELETE ON public.divine_fragment_vehicle_client_contract FOR EACH ROW EXECUTE FUNCTION public.shardkeep_vehicle_client_seal_guard();
CREATE TRIGGER divine_fragment_vehicle_client_contract_no_truncate BEFORE TRUNCATE ON public.divine_fragment_vehicle_client_contract FOR EACH STATEMENT EXECUTE FUNCTION public.shardkeep_vehicle_client_seal_guard();
REVOKE ALL ON FUNCTION public.shardkeep_vehicle_client_seal_guard() FROM PUBLIC;
INSERT INTO public.divine_fragment_vehicle_client_contract(record) SELECT public.shardkeep_divine_fragment_contract();
SELECT public.shardkeep_divine_fragment_source();
